            \multicolumn{1}{ c  }{\multirow{12}{*}} & \multicolumn{1}{ r|  }{$A_{\tilde2 \tilde2 3}$ } & 0 & 0 & 0 & 2 & 1 & 0 & 0 \\
            \multicolumn{1}{ c  }{\multirow{12}{*}} & \multicolumn{1}{ r|  }{$Y_{\tilde2 33}$ } & 0 & 0 & 0 & 1 & 2 & 1 & 0 \\
        \end{tabular}
    \end{center}
\caption{Collection of all interaction terms with three LQ fields that result in a vanishing total weak hypercharge $Y$. The numbers in the table indicate the number of the corresponding LQ fields interacting in the vertex. The same combinations with all fields replaced by their anti-fields correspond to the Hermitian conjugates and are also valid solutions.  }
\label{tab:triple}
\end{table}


However, not all of these combinations can be implemented. Since the Lagrangian is symmetric under the exchange of identical bosons and the color terms are totally anti-symmetric, the $SU(2)_L$ part needs to be anti-symmetric for identical bosons as well. This is not satisfied by $Y_{112}, Y_{11\tilde{2}}, Y_{\tilde{2} \tilde{2} \tilde{2}}, A_{\tilde{2}\tilde{2}3}$ in Table~\ref{tab:triple}. Hence, the Lagrangian is composed of the terms~\cite{Kovalenko:2002eh, Klapdor-Kleingrothaus:2002rvk, Arnold:2012sd, Hambye:2017qix}


\begin{align}
    \begin{aligned}
        \mathcal{L}_{3 \Phi} 
        &= \phantom{12} A_{1\tilde{2}\tilde{2}} \ \Phi_{1, c_1} \left(\Phi_{\tilde{2}, c_2}^\intercal i\sigma_2 \Phi_{\tilde{2}, c_3}\right)
        + A_{\tilde{1}2\tilde{2}} \ \Phi_{\tilde{1}, c_1} \left(\Phi_{2, c_2}^\intercal i\sigma_2 \Phi_{\tilde{2}, c_3}\right) \\
        &\phantom{12}+ Y_{1 \tilde{1}2} \ \Phi_{1, c_1} \Phi_{\tilde{1}, c_2} \left( \Phi_{2, c_3}^\intercal i \sigma_2 H \right)
        + Y_{123} \ \Phi_{1, c_1} \left(H^\dagger \left( \sigma \cdot \Phi_{3, c_3} \right) \Phi_{2, c_2}\right) \\
        &\phantom{12}+ Y_{1\tilde{2}3} \ \Phi_{1, c_1} \left(\Phi_{\tilde{2}, c_2}^\intercal i \sigma_2 \left( \sigma \cdot \Phi_{3, c_3} \right) H\right)
        + Y_{\tilde{1}23} \ \Phi_{\tilde{1}, c_1} \left(\Phi_{2, c_2}^\intercal i \sigma_2 \left( \sigma \cdot \Phi_{3, c_3} \right) H\right)  \\
        &\phantom{12}+ Y_{233} \ \left(H^\dagger \sigma^I \Phi_{2, c_1}\right)\left( \Phi^J_{3, c_2} i \epsilon^{IJK} \Phi^K_{3, c_3}\right) \\
        &\phantom{12}+  Y_{\tilde{2}33} \ \left(\Phi_{\tilde{2}, c_1}^\intercal i \sigma_2 \sigma^I H\right) \left( \Phi^J_{3, c_2} i\epsilon^{IJK}\Phi^K_{3, c_3} \right) \\
        &\phantom{12}+ \text{h.c.} \,.& 
        \label{eq:LQ_triplet_interactions}
    \end{aligned}
\end{align}


The Levi-Civita tensors $\epsilon^{c_1 c_2 c_3}$ are omitted, such that i.e.~the first term would read $A_{1\tilde{2}\tilde{2}} \epsilon^{c_1c_2c_3} \ \Phi_{1, c_1} \left(\Phi_{\tilde{2}, c_2}^\intercal i\sigma_2 \Phi_{\tilde{2}, c_3}\right)$ in the full notation. 

\subsection{Quartic LQ Interactions ($\mathcal{L}_{4 \Phi}$)}
To get four-LQ interaction terms in the Lagrangian, one needs to combine two LQs and two anti-LQs, since


\begin{equation}
3 \otimes \overline{3} \otimes 3 \otimes \overline{3} = 1 \oplus 1 \oplus 8 \oplus 8 \oplus 8 \oplus 8 \oplus 10 \oplus \overline{10} \oplus 27
\label{eq:SU(3)_singlets}
\end{equation}
is the only tensor product of four $SU(3)_{c}$ fundamental representations $\left(3, \overline{3}\right)$ that contains a singlet. Trivial combinations of LQ fields that contribute to the four-LQ Lagrangian are of the type
\begin{equation}
\begin{aligned}
Y^{(1)}_{a} \left(\Phi^\dagger_{a, c_1} \Phi_{a, c_1}\right) \left( \Phi^\dagger_{a, c_2} \Phi_{a, c_2} \right)\,, \\
Y^{(1)}_{ab} \left(\Phi^\dagger_{a, c_1} \Phi_{a, c_1}\right) \left( \Phi^\dagger_{b, c_2} \Phi_{b, c_2} \right)\,,
\end{aligned}
\label{eq:obviouscombination}
\end{equation}


where $a \neq b \in \left\{1,\tilde{1}, 2, \tilde{2}, 3 \right\}$. All additional combinations that result in a vanishing total weak hypercharge $Y$ are given in Tab.~\ref{tab:quartic}. 


\begin{table}[t]
    \renewcommand{\arraystretch}{1.2}
    \begin{center}
        \begin{tabular}{rr|c c c c c }
            & & \multicolumn{5}{c}{LQ Fields (and their $Y$)}\\
            & & $\Phi_1,\Phi_1^\dagger$  & $\Phi_{\tilde{1}},\Phi_{\tilde{1}}^\dagger$ & $\Phi_2,\Phi_2^\dagger$ & $\Phi_{\tilde{2}},\Phi_{\tilde{2}}^\dagger$ & $\Phi_3,\Phi_3^\dagger$ \\ [0.5ex] 
            & & $-\frac{1}{3}, \frac{1}{3}$ & $-\frac{4}{3}, \frac{4}{3}$ & $\frac{7}{6}, -\frac{7}{6}$ & $\frac{1}{6}, -\frac{1}{6}$& $-\frac{1}{3}, \frac{1}{3}$ \\ [0.7ex]
            \cline{1-7}
            \multicolumn{1}{ c  }{\multirow{8}{*}{ \rotatebox[origin=c]{90}{Interaction Terms}} } & \multicolumn{1}{r|}{$Y_{1113}$ } & $1,2$ & $0,0$ & $0,0$ & $0,0$ & $1,0$ \\
            \multicolumn{1}{ c  }{\multirow{8}{*}} & \multicolumn{1}{ r|  }{$Y_{1\tilde{1}\tilde{1}3}$ } & $0,1$ & $1,1$ & $0,0$ & $0,0$ & $1,0$ \\
            \multicolumn{1}{ c  }{\multirow{8}{*}} & \multicolumn{1}{ r|  }{$Y_{1\tilde{1}\tilde{2}2}$ } & $0,1$ & $1,0$ & $1,0$ & $0,1$ & $0,0$ \\
            \multicolumn{1}{ c  }{\multirow{8}{*}} & \multicolumn{1}{ r|  }{$Y_{1223}$ } & $0,1$ & $0,0$ & $1,1$ & $0,0$ & $1,0$ \\
            \multicolumn{1}{ c  }{\multirow{8}{*}} & \multicolumn{1}{ r|  }{$Y_{1\tilde{2}\tilde{2}3}$ } & $0,1$ & $0,0$ & $0,0$ & $1,1$ & $1,0$ \\
            \multicolumn{1}{ c  }{\multirow{8}{*}} & \multicolumn{1}{ r|  }{$Y_{1313}$ } & $0,2$ & $0,0$ & $0,0$ & $0,0$ & $2,0$ \\
            \multicolumn{1}{ c  }{\multirow{8}{*}} & \multicolumn{1}{ r|  }{$Y_{1333}$ } & $0,1$ & $0,0$ & $0,0$ & $0,0$ & $2,1$ \\
            \multicolumn{1}{ c  }{\multirow{8}{*}} & \multicolumn{1}{ r|  }{$Y_{\tilde{1}\tilde{2}23}$ } & $0,0$ & $0,1$ & $0,1$ & $1,0$ & $1,0$ \\
        \end{tabular}
    \end{center}
\caption{Collection of all interaction terms with four LQ fields that result in a vanishing total weak hypercharge $Y$. We do not include the trivial combinations stated in Eq.~(\ref{eq:obviouscombination}). The numbers in the table indicate the number of the corresponding LQ fields in the interaction term. The same combinations with all fields replaced by their anti-fields (i.e. with the pairs listed in the table permuted) correspond to the Hermitian conjugates and are also valid solutions. }
\label{tab:quartic}
\end{table}


Taking into account $SU(2)_L$ invariance, the terms corresponding to $Y_{1113}$ and $Y_{1\tilde{1}\tilde{1}3}$ cannot be implemented, but besides $Y^{(1)}_{2}, Y^{(1)}_{\tilde{2}}, Y^{(1)}_{3}, Y^{(1)}_{2\tilde{2}}, Y^{(1)}_{23}$ and $Y^{(1)}_{\tilde{2}3}$, further independent terms with the same fields exist, originating from the different $SU(2)_L$ singlets that can be constructed. Regarding $SU(3)_c$, except for the case when two fields are identical, there are two possibilities to contract the color indices tracing back to the two singlets in Eq.~\ref{eq:SU(3)_singlets}. We distinguish them by different couplings $Y$ and $Y^\prime$ for full generality. This yields the Lagrangian
















\begin{align*}
    \begin{aligned}
        \mathcal{L}_{4 \Phi} 
        = &\phantom{+1} \frac{1}{2}\sum_{a} Y^{(1)}_{a} \left( \Phi_{a, c_1}^\dagger \Phi_{a, c_1} \right)\left(\Phi_{a, c_2}^\dagger \Phi_{a, c_2}\right) \\
        &+ \frac{1}{2} \sum_{a = 2, \tilde{2}, 3} Y^{(3)}_{a}  \left( \Phi_{a, c_1}^\dagger \Phi_{a, c_2} \right) \left(\Phi_{a, c_2}^\dagger \Phi_{a, c_1}\right)\\
        &+ \frac{1}{2} Y^{(5)}_{3} \left( \Phi_{3, c_1}^{I\dagger} \Phi_{3, c_1}^{J}  \Phi_{3, c_2}^{I\dagger} \Phi_{3, c_2}^{J}\right) \\
        	&+\sum_{a \neq b} \left( Y^{(1)}_{ab} \ \delta_{c_1 c_2} \delta_{c_3 c_4} + Y^{\prime(1)}_{ab} \ \delta_{c_1 c_4} \delta_{c_2 c_3} \right)  \left( \Phi_{a, c_1}^\dagger \Phi_{a, c_2}\right) \left( \Phi_{b, c_3}^\dagger \Phi_{b, c_4} \right) \\
         &+\left( Y^{(3)}_{2\tilde{2}} \ \delta_{c_1 c_2} \delta_{c_3 c_4} + Y^{\prime(3)}_{2\tilde{2}} \ \delta_{c_1 c_4} \delta_{c_2 c_3} \right)  \left( \Phi_{2, c_1}^\dagger \Phi_{\tilde{2}, c_2}\right) \left( \Phi_{\tilde{2}, c_3}^\dagger \Phi_{2, c_4} \right) \\
      \end{aligned}
\end{align*}
\begin{align}
	\begin{aligned}
        &+ \sum_{a = 2, \tilde{2}}\left( Y^{(3)}_{a3} \ \delta_{c_1 c_2} \delta_{c_3 c_4} + Y^{\prime(3)}_{a3} \ \delta_{c_1 c_4} \delta_{c_2 c_3} \right)\left(\Phi_{a, c_1}^\dagger \sigma^I \Phi_{a, c_2} \right)\left(\Phi_{3, c_3}^{J\dagger} i\epsilon^{IJK} \Phi_{3, c_4}^K \right) \\
        &+ \Bigg[ \phantom{+} \sum_{a =   2, \tilde{2} } \left(Y_{1aa3} \ \delta_{c_1 c_2} \delta_{c_3 c_4} + Y^\prime_{1aa3} \ \delta_{c_1 c_4} \delta_{c_2 c_3} \right) \Phi^\dagger_{1, c_1}  \left(\Phi_{a, c_3}^\dagger \big(\sigma \cdot \Phi_{3, c_4} \big) \Phi_{a, c_2} \right)  \\
        &\phantom{12 +\Bigg[}+ \left(Y_{\tilde{1} \tilde{2} 2 3}\  \delta_{c_1 c_2} \delta_{c_3 c_4} + Y^\prime_{\tilde{1} \tilde{2} 2 3} \ \delta_{c_1 c_4} \delta_{c_2 c_3} \right) \Phi_{\tilde{1}, c_1}^\dagger  \left(\Phi_{2, c_3}^\dagger \big(\sigma \cdot \Phi_{3, c_4} \big)\Phi_{\tilde{2}, c_2} \right) \\
         &\phantom{12 + \Bigg[}+ \left(Y_{1 \tilde{1} \tilde{2} 2} \ \delta_{c_1 c_2} \delta_{c_3 c_4} + Y^\prime_{1 \tilde{1} \tilde{2} 2}\  \delta_{c_1 c_4} \delta_{c_2 c_3} \right) \Phi^\dagger_{1, c_1} \Phi_{\tilde{1}, c_2} \big(\Phi_{\tilde{2}, c_3}^\dagger  \Phi_{2, c_4}\big) \\
         &\phantom{12 + \Bigg[}+ \frac{1}{2} Y_{1 3 1 3} \ \delta_{c_1 c_2} \delta_{c_3 c_4} \left(\Phi^\dagger_{1, c_1} \Phi^I_{3, c_2} \Phi^\dagger_{1, c_3} \Phi^I_{3, c_4} \right) \\
         &\phantom{12 + \Bigg[}+ Y_{1 3 3 3} \ \delta_{c_1 c_2} \delta_{c_3 c_4} \left(\Phi^\dagger_{1, c_1} \Phi^I_{3, c_2} \Phi^{J \dagger}_{3, c_3} \Phi^K_{3, c_4} i\epsilon^{IJK} \right) \text{~ + h.c.} \Bigg]\,,
        \label{eq:LQ_quartic_interactions}
    \end{aligned}
\end{align}


with $a, b \in \left \{1, \tilde{1}, 2, \tilde{2}, 3 \right \}$ unless stated otherwise. Note that we set $Y^{(1)}_{ab} = Y^{(1)}_{ba}$ and $Y^{(1)\prime}_{ab} = Y^{(1)\prime}_{ba}$ for $a \neq b$, since they correspond to the same terms. The Feynman rules are expressed using only one of them, i.e. $Y^{(1)}_{\tilde{1}3}$, but not $Y^{(1)}_{3\tilde{1}}$.  









