        \Phi^{-4/3} &\equiv 
        \renewcommand{\arraystretch}{1.5}
                    \begin{pmatrix}
                        \Phi_{\tilde{1}}^{-4/3} \\ 
                        \Phi^{-4/3}_{3}
                    \end{pmatrix} \,,
